        shingleSize: {{ shingleSize }}
        sampleSize: {{ sampleSize }}
        ignoreNearExpectedFromAbove:
          amount: {{ amount }}
          ratio: {{ ratio }}
        ignoreNearExpectedFromBelow:
          amount: {{ amount }}
          ratio: {{ ratio }}
